"""Vista móvil Grafito: pantalla/tacto/teclado en canales independientes."""
from victor.integrations.keyboard_client import KEYBOARD_JS

POINTER_JS = r"""
class PointerChannel {
 constructor(socket,notice,onWindow){this.ws=socket;this.notice=notice;this.onWindow=onWindow;this.seq=0;this.queue=[];this.move=null;this.pending=null;this.closed=false;this.lastSeen=Date.now();this.deadline=0;
  socket.onmessage=e=>{try{const m=JSON.parse(e.data);this.lastSeen=Date.now();if(m.type==='pong')return;if(m.type==='pointer_pending'){this.deadline=Date.now()+130000;this.notice(m.message);return;}if(m.type==='pointer_ack'){if(!this.pending||m.seq!==this.pending.seq)throw Error('Confirmación de puntero fuera de secuencia.');this.pending=null;if(m.ok){this.onWindow(m);this.notice('Control táctil activo');}else this.notice(m.error||'Puntero detenido.');this.pump();return;}if(m.type==='disconnected')throw Error(m.message);}catch(e){this.fail(e.message);}};
  socket.onclose=()=>this.fail('Puntero desconectado. Revisa Wi-Fi y genera otro QR.');socket.onerror=()=>this.fail('Error de puntero. Revisa HTTPS y Wi-Fi.');
  this.timer=setInterval(()=>{if(this.closed)return;if(Date.now()-this.lastSeen>15000||this.pending&&Date.now()>this.deadline){this.fail('Puntero sin respuesta. Vuelve a emparejar.');return;}if(socket.readyState===1)socket.send(JSON.stringify({type:'ping'}));},3000);
 }
 push(event){if(this.closed)throw Error('Control táctil desconectado.');if(event.action==='move')this.move=event;else{if(this.move){this.queue.push(this.move);this.move=null;}if(this.queue.length>=16)throw Error('Suelta la pantalla y espera al PC.');this.queue.push(event);}this.pump();}
 pump(){if(this.closed||this.pending||this.ws.readyState!==1)return;const item=this.queue.shift()||this.move;if(!item)return;if(item===this.move)this.move=null;this.pending={type:'pointer_event',seq:++this.seq,...item};this.deadline=Date.now()+10000;this.ws.send(JSON.stringify(this.pending));}
 fail(message){if(this.closed)return;this.closed=true;this.queue=[];this.move=null;this.pending=null;clearInterval(this.timer);this.ws.close();this.notice(message);}
}
function imagePosition(clientX,clientY,rect,width,height){const scale=Math.min(rect.width/width,rect.height/height),w=width*scale,h=height*scale;if(!w||!h)return null;const x=(clientX-rect.left-(rect.width-w)/2)/w,y=(clientY-rect.top-(rect.height-h)/2)/h;return x>=0&&x<=1&&y>=0&&y<=1?{x,y}:null;}
"""

PAGE = r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>VICTOR.IA · Remoto</title><style>
@font-face{font-family:Inter;src:url('/assets/inter.ttf') format('truetype');font-weight:100 900;font-display:swap}
*{box-sizing:border-box}body{margin:0;background:#191c22;color:#e9eaf1;font:13px Inter,system-ui,sans-serif}header{padding:24px 22px 18px;border-bottom:1px solid #30333e;display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:16px;margin:0 0 10px;font-weight:650}h1 span{color:#83afff}small,.hint{color:#9196a5;line-height:1.6}main{padding:18px;max-width:1100px;margin:auto}label{display:block;font-weight:600;font-size:12px;margin-bottom:9px}button,input,textarea,select{font:inherit;color:inherit;border:1px solid #373c48;border-radius:9px;background:#22252e;padding:12px}button{cursor:pointer;touch-action:manipulation;min-height:42px}button:hover{border-color:#83afff}button.primary{background:#588ad8;border-color:#749de1;color:white}button.danger{background:#35262b;border-color:#70434c;color:#f28f95}button:disabled{opacity:.5}input,textarea{width:100%;font-size:16px;min-height:42px}textarea{resize:none;height:44px}.row{display:flex;gap:9px;align-items:center}.row>*{flex:1}.row .smallbutton{flex:0 0 142px}.top{display:grid;grid-template-columns:1fr 142px;gap:8px;margin-bottom:18px}.badge{white-space:nowrap;border:1px solid #315746;background:#21372f;color:#68cca4;padding:6px 10px;border-radius:16px;font-size:11px;font-weight:600}.section-head{display:flex;justify-content:space-between;margin:10px 0}.section-head span{color:#83afff;font-size:11px}#screenBox{height:clamp(230px,43vh,640px);display:flex;align-items:center;justify-content:center;border:1px solid #455876;border-radius:10px;overflow:hidden;background:#22252e;position:relative}#view{width:100%;height:100%;display:block;object-fit:contain;touch-action:none;user-select:none;-webkit-user-select:none}#placeholder{position:absolute;pointer-events:none;color:#9196a5;text-align:center;max-width:85%}.hint{text-align:center;margin:14px 0 20px;font-size:11px}.controls{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}.controls button{padding:9px 3px;font-size:12px;min-width:0}#modifiers{margin-top:8px;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}#modifiers label{background:#22252e;border:1px solid #373c48;border-radius:8px;padding:10px;margin:0;text-align:center;font-weight:400}#modifiers input{width:auto;min-height:0;margin:0 6px 0 0;accent-color:#83afff}#keyboardBox{margin-top:17px}#keyboardBox[hidden]{display:none}#keyboardStatus,#pointerStatus,#status{font-size:11px;color:#9196a5;line-height:1.5;margin:10px 0;overflow-wrap:anywhere}footer{padding:16px 18px calc(18px + env(safe-area-inset-bottom));max-width:1100px;margin:auto}footer .hint{margin:14px 0 0}.active{border-color:#83afff!important;color:#83afff!important}
@media(min-width:700px){#screenBox{height:60vh}.controls{grid-template-columns:repeat(7,1fr)}}
</style></head><body>
<header><div><h1>◈ <span>VICTOR.IA</span> Remoto</h1><small>Sesión segura · Control remoto del escritorio</small></div><span class="badge" id="connection">● Conectando</span></header>
<main><div class="top"><div><label for="window">Ventana destino</label><input id="window" value="Escritorio completo" aria-label="Ventana destino"></div><div><label>Transmisión</label><button id="screen" style="width:100%">↻ Renovar</button></div></div>
<div class="section-head"><label>Vista del PC</label><span id="live">Esperando imagen</span></div>
<div id="screenBox"><img id="view" alt="Pantalla en vivo del PC" draggable="false"><div id="placeholder">Confirma compartir la pantalla en tu PC. La transmisión continúa mientras la sesión permanezca conectada.</div></div>
<div class="hint">Desliza un dedo para mover · Toca para hacer clic · Dos dedos para scroll</div>
<div class="row"><button id="keyboard" class="primary">⌨ Teclado</button><button id="touchMode">✧ Control táctil</button></div>
<div id="pointerStatus">Control táctil: espera la conexión.</div>
<section id="keyboardBox" hidden><label for="typing">Escribir en el PC · envío en tiempo real</label><div class="row"><textarea id="typing" rows="1" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="enter" placeholder="Escribe en el campo enfocado…"></textarea><button id="sendText" class="primary" style="flex:0 0 92px">Enviar ↑</button></div><p id="keyboardStatus">Espera a que conecte el teclado.</p></section>
<label style="margin-top:18px">Teclas rápidas</label><div class="controls"><button data-key="enter">Intro</button><button data-key="esc">Esc</button><button data-key="backspace">Borrar</button><button data-key="tab">Tab</button><button data-key="delete">Supr</button><button data-key="up">↑</button><button data-key="left">←</button><button data-key="right">→</button><button data-key="down">↓</button><button data-key="f4">F4</button><button data-key="a">A</button><button data-key="c">C</button><button data-key="v">V</button></div>
<div id="modifiers"><label><input id="ctrl" type="checkbox">Ctrl</label><label><input id="alt" type="checkbox">Alt</label><label><input id="shift" type="checkbox">Shift</label></div><small>Ctrl, Alt y Shift se liberan tras cada atajo.</small><p id="status" role="status" aria-live="polite">Conectando con el PC…</p></main>
<footer><div class="row"><button id="approval">ⓘ Aprobación pendiente</button><button id="stop" class="danger">■ Detener sesión</button></div><div class="hint">Los atajos sensibles requieren aprobación en el PC.<br>Si se desconecta: misma Wi-Fi, servidor HTTPS activo y un QR nuevo.</div></footer>
<script>
'use strict';
const status=document.getElementById('status'),target=document.getElementById('window'),view=document.getElementById('view'),typing=document.getElementById('typing');
let ws,video,pointerChannel,keyboardChannel,session='',pending=false,frame=null,metadata=null,imageURL='',imageTime=0,imageSequence=0,lastControl=Date.now(),running=true,focusInfo=null,focusedWindow='',targetOwner='',mirrored='',composing=false;
const code=location.hash.slice(1);history.replaceState(null,'',location.pathname);
function connect(path,auth){return new Promise((resolve,reject)=>{const s=new WebSocket('wss://'+location.host+path);const timeout=setTimeout(()=>{s.close();reject(Error('HTTPS no responde. Revisa Wi-Fi y certificado. Reinicia el servidor del PC y escanea un QR nuevo si caducó.'));},8000);s.onopen=()=>s.send(JSON.stringify(auth));s.onerror=()=>{clearTimeout(timeout);s.close();reject(Error('No pude conectar con HTTPS. Acepta el certificado local de esta IP y revisa Wi-Fi.'));};s.onclose=()=>{clearTimeout(timeout);reject(Error('Conexión cerrada. Genera un QR nuevo.'));};s.onmessage=e=>{clearTimeout(timeout);try{const m=JSON.parse(e.data);if(m.error)throw Error(m.error);resolve([s,m]);}catch(e){s.close();reject(e);}};});}
function send(tool,args){if(!running||!ws||ws.readyState!==1)return false;if(pending){status.textContent='Hay una acción esperando autorización en el PC.';return false;}pending=true;ws.send(JSON.stringify({tool,args}));status.textContent='Confirma compartir pantalla en el PC.';return true;}
function locationOnImage(x,y){return frame?imagePosition(x,y,view.getBoundingClientRect(),frame.width,frame.height):null;}
function pointer(x,y,action){const p=locationOnImage(x,y);if(!p||Date.now()-imageTime>3000){document.getElementById('pointerStatus').textContent='Espera una imagen actual antes de tocar.';return;}try{if(!pointerChannel)throw Error('Espera el canal táctil.');pointerChannel.push({window:target.value.trim()||'Escritorio completo',x:p.x,y:p.y,frame_id:frame.id,action});}catch(e){document.getElementById('pointerStatus').textContent=e.message;}}
const points=new Map();let gesture=null,lastMove=0,lastScroll=0;
view.onpointerdown=e=>{e.preventDefault();points.set(e.pointerId,[e.clientX,e.clientY]);view.setPointerCapture(e.pointerId);if(points.size===1)gesture={startX:e.clientX,startY:e.clientY,drag:false,scroll:false,scrollY:e.clientY};if(points.size>=2&&gesture){gesture.scroll=true;gesture.scrollY=[...points.values()].reduce((s,p)=>s+p[1],0)/points.size;}};
view.onpointermove=e=>{if(!points.has(e.pointerId)||!gesture)return;e.preventDefault();points.set(e.pointerId,[e.clientX,e.clientY]);if(gesture.scroll&&points.size>=2){const values=[...points.values()],y=(values[0][1]+values[1][1])/2;if(Math.abs(y-gesture.scrollY)>18&&Date.now()-lastScroll>90){pointer((values[0][0]+values[1][0])/2,y,y<gesture.scrollY?'down':'up');lastScroll=Date.now();gesture.scrollY=y;}}else if(!gesture.scroll){if(Math.hypot(e.clientX-gesture.startX,e.clientY-gesture.startY)>4)gesture.drag=true;if(gesture.drag&&Date.now()-lastMove>40){pointer(e.clientX,e.clientY,'move');lastMove=Date.now();}}};
view.onpointerup=e=>{if(gesture&&!gesture.scroll){pointer(e.clientX,e.clientY,gesture.drag?'move':'click');if(!gesture.drag&&focusInfo&&focusInfo.editable)showKeyboard();}points.delete(e.pointerId);if(!points.size)gesture=null;};view.onpointercancel=e=>{points.delete(e.pointerId);if(!points.size)gesture=null;};
const keyboardStatus=document.getElementById('keyboardStatus');
function keyWindow(){return target.value==='Escritorio completo'?focusedWindow:target.value.trim();}
function keyboardNotice(message){keyboardStatus.textContent=message;if(keyboardChannel&&keyboardChannel.closed){typing.disabled=true;mirrored='';typing.value='';}}
function showKeyboard(){document.getElementById('keyboardBox').hidden=false;typing.disabled=!keyboardChannel||keyboardChannel.closed;if(!typing.disabled){typing.focus({preventScroll:true});try{if(navigator.virtualKeyboard)navigator.virtualKeyboard.show();}catch(_){}}}
document.getElementById('keyboard').onclick=showKeyboard;
document.getElementById('touchMode').onclick=()=>{typing.blur();document.getElementById('keyboardBox').hidden=true;document.getElementById('touchMode').classList.add('active');};
function focusChanged(info){const changed=!focusInfo||focusInfo.field!==info.field||focusInfo.owner!==info.owner||focusInfo.editable!==info.editable;focusInfo=info;if(info.window&&!info.window.includes('VICTOR.IA'))focusedWindow=info.window;if(info.window===target.value)targetOwner=info.owner||'';if(changed)clearMirror();if(changed&&info.editable&&(target.value==='Escritorio completo'||info.window===target.value||(targetOwner&&info.owner===targetOwner))){showKeyboard();keyboardNotice('Campo detectado. Si el navegador no abre su teclado, pulsa Teclado.');}}
function transmit(events){if(!events.length)return true;try{if(!keyboardChannel)throw Error('Espera a que conecte el teclado.');if(!keyWindow())throw Error('Toca un campo de texto del PC antes de escribir.');keyboardChannel.push(events);return true;}catch(e){keyboardNotice(e.message);return false;}}
function modifiers(){return ['ctrl','alt','shift'].filter(k=>document.getElementById(k).checked);}
function clearMirror(){mirrored='';typing.value='';}
function special(key,mods=modifiers()){if(transmit([VictorKeys.keyEvent(key,mods)]))clearMirror();}
function commit(){if(composing)return;try{const events=VictorKeys.editEvents(mirrored,typing.value),mods=modifiers();if(mods.length&&events.length===1&&events[0].kind==='text'&&/^[a-z0-9]$/i.test(events[0].text)){special(events[0].text,mods);return;}if(transmit(events)){mirrored=Array.from(typing.value).slice(-128).join('');typing.value=mirrored;typing.setSelectionRange(typing.value.length,typing.value.length);}else clearMirror();}catch(e){keyboardNotice(e.message);clearMirror();}}
typing.oncompositionstart=()=>composing=true;typing.oncompositionend=()=>{composing=false;commit();};typing.oninput=commit;
typing.onkeydown=e=>{if(composing||e.isComposing)return;const mods=[...new Set(modifiers().concat(e.ctrlKey?['ctrl']:[],e.altKey?['alt']:[],e.shiftKey?['shift']:[],e.metaKey?['win']:[]))];if(['Enter','Escape','Backspace','Delete','Tab','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown','F4'].includes(e.key)||((e.ctrlKey||e.altKey||e.metaKey)&&/^[a-z0-9]$/i.test(e.key))){e.preventDefault();special(e.key,mods);}};
typing.onbeforeinput=e=>{if(composing||e.isComposing)return;if(e.inputType==='deleteContentBackward'&&!typing.value){e.preventDefault();special('backspace');}else if(e.inputType==='insertLineBreak'||e.inputType==='insertParagraph'){e.preventDefault();special('enter');}};
document.getElementById('sendText').onclick=()=>{typing.blur();commit();};
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>special(b.dataset.key));
target.addEventListener('change',()=>{targetOwner='';clearMirror();});
document.getElementById('screen').onclick=()=>send('remote_screen_stream',{});
document.getElementById('approval').onclick=()=>{status.textContent='Revisa VICTOR en el PC. El celular no puede aprobar sus propios permisos ni atajos de alto riesgo.';};
function disconnect(message){if(!running)return;running=false;pending=false;points.clear();if(keyboardChannel)keyboardChannel.fail(message);if(pointerChannel)pointerChannel.fail(message);if(ws)ws.close();if(video)video.close();typing.disabled=true;view.style.opacity='.45';document.getElementById('connection').textContent='● Desconectado';status.textContent=message;}
document.getElementById('stop').onclick=()=>disconnect('Sesión detenida. Genera otro QR para reconectar.');
window.addEventListener('pagehide',()=>disconnect('Sesión cerrada.'));
setInterval(()=>{if(!running)return;if(ws&&ws.readyState===1){if(Date.now()-lastControl>15000){disconnect('Se perdió la conexión. Revisa Wi-Fi, HTTPS y escanea un QR nuevo. No se repetirán teclas pendientes.');return;}ws.send(JSON.stringify({type:'ping'}));}if(video&&video.readyState===1&&imageTime&&Date.now()-imageTime>3000){view.style.opacity='.45';document.getElementById('live').textContent='Imagen sin actualizar';}},3000);
(async()=>{try{if(!code)throw Error('Abre el enlace completo del QR generado en tu PC.');[ws,{session}]=await connect('/control',{code});lastControl=Date.now();document.getElementById('connection').textContent='● Conectado';status.textContent='Conectado. Autoriza compartir pantalla en el PC.';
ws.onmessage=e=>{try{const m=JSON.parse(e.data);lastControl=Date.now();if(m.type==='pong')return;status.textContent=m.message||m.error||'Listo';if(m.done)pending=false;}catch(_){disconnect('Respuesta de control inválida. Genera otro QR.');}};ws.onclose=()=>disconnect('Sesión cerrada. Revisa Wi-Fi/HTTPS y genera otro QR; si caducó el certificado, reinicia el servidor.');
connect('/keyboard',{session}).then(([s])=>{keyboardChannel=new VictorKeys.Channel(s,keyWindow,keyboardNotice,focusChanged);keyboardNotice('Teclado conectado · texto normal autorizado por QR');}).catch(e=>keyboardNotice(e.message));
connect('/pointer',{session}).then(([s])=>{pointerChannel=new PointerChannel(s,m=>document.getElementById('pointerStatus').textContent=m,m=>{if(m.window&&!m.window.includes('VICTOR.IA'))focusedWindow=m.window;});document.getElementById('pointerStatus').textContent='Desliza o toca la imagen para autorizar el control en el PC.';}).catch(e=>document.getElementById('pointerStatus').textContent=e.message);
[video]=await connect('/screen',{session});video.binaryType='blob';video.onclose=()=>disconnect('La pantalla se desconectó. Revisa Wi-Fi y genera un QR nuevo.');video.onerror=()=>disconnect('Falló el canal de pantalla. Revisa certificado y red.');video.onmessage=e=>{if(e.data instanceof Blob){const serial=++imageSequence,info=metadata,url=URL.createObjectURL(e.data),decoded=new Image();decoded.onload=()=>{if(serial!==imageSequence||!running||!info){URL.revokeObjectURL(url);return;}if(imageURL)URL.revokeObjectURL(imageURL);imageURL=url;frame=info;view.src=url;imageTime=Date.now();view.style.opacity='1';document.getElementById('placeholder').hidden=true;document.getElementById('live').textContent='En vivo';};decoded.onerror=()=>{URL.revokeObjectURL(url);status.textContent='No pude decodificar la imagen recibida.';};decoded.src=url;}else{try{const m=JSON.parse(e.data);if(m.frame)metadata=m.frame;else status.textContent=m.error||'Pantalla detenida';}catch(_){status.textContent='Imagen inválida.';}}};send('remote_screen_stream',{});
}catch(e){disconnect(e.message);status.textContent=e.message;}})();
</script></body></html>'''
PAGE = PAGE.replace('<script>', '<script>\n'+KEYBOARD_JS+'\n'+POINTER_JS, 1)
